#!/usr/bin/env bash
# Shared helpers for the local WordPress admin-RCE lab.
set -euo pipefail

LAB_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
BASE_URL="${BASE_URL:-http://127.0.0.1:8899}"
CREDENTIALS_FILE="${CREDENTIALS_FILE:-$LAB_DIR/.admin-credentials}"

# Credentials are generated by the setup scripts and stored outside Git.
if [ -z "${ADMIN_USER:-}" ] && [ -f "$CREDENTIALS_FILE" ]; then
  ADMIN_USER="$(sed -n 's/^ADMIN_USER=//p' "$CREDENTIALS_FILE" | head -1)"
fi
if [ -z "${ADMIN_PASS:-}" ] && [ -f "$CREDENTIALS_FILE" ]; then
  ADMIN_PASS="$(sed -n 's/^ADMIN_PASS=//p' "$CREDENTIALS_FILE" | head -1)"
fi
ADMIN_USER="${ADMIN_USER:-admin}"

[ -n "${ADMIN_PASS:-}" ] || {
  echo "ERROR: no admin password. Set ADMIN_PASS or run ./bin/setup-local.sh / ./bin/setup-docker.sh first." >&2
  exit 1
}

COOKIE_JAR="${COOKIE_JAR:-$LAB_DIR/.cookies.txt}"
TMP_DIR="$(mktemp -d)"
trap 'rm -rf "$TMP_DIR"' EXIT

fail() {
  echo "ERROR: $*" >&2
  exit 1
}

# wp_login <output-html>
# Authenticates through wp-login.php exactly like a browser and verifies that
# the resulting session has access to wp-admin.
wp_login() {
  local out="$1"

  curl -sS --max-time 20 -c "$COOKIE_JAR" "$BASE_URL/wp-login.php" -o /dev/null

  curl -sS --max-time 30 -b "$COOKIE_JAR" -c "$COOKIE_JAR" -L \
    --data-urlencode "log=$ADMIN_USER" \
    --data-urlencode "pwd=$ADMIN_PASS" \
    --data-urlencode "wp-submit=Log In" \
    --data-urlencode "redirect_to=$BASE_URL/wp-admin/" \
    --data-urlencode "testcookie=1" \
    -o "$out" \
    "$BASE_URL/wp-login.php"

  if grep -q 'id="login_error"' "$out"; then
    fail "admin login failed: $(grep -oE '<p[^>]*>[^<]*' "$out" | sed -n '2p')"
  fi

  if ! grep -q 'wp-admin' "$out"; then
    fail "admin login did not reach wp-admin (bad credentials or blocked login)"
  fi

  echo "[+] logged in as '$ADMIN_USER' -> $BASE_URL/wp-admin/"
}

# nonce <html-file> <input-name>
nonce() {
  local file="$1" name="$2" value
  value="$(grep -oE "name=\"$name\" value=\"[A-Za-z0-9]+\"" "$file" | head -1 | sed -E 's/.*value="([A-Za-z0-9]+)"/\1/' || true)"
  [ -n "$value" ] || fail "could not find nonce '$name' in $file"
  printf '%s' "$value"
}
